const received = $input.first().json;
const response = received.body;
const now = new Date().toISOString();
const out = (status, code, data = null) => [{json:{status,code,operation:"entitlement",timestamp:now,data}}];
if (received.statusCode !== 200 || !response || typeof response !== 'object') return out('unavailable','VERIFIED_PRODUCT_DATA_REQUIRED');
const wallet = response.wallet;
const op = "entitlement";
if (op === 'entitlement') {
  const e = response.entitlement;
  return e && e.source === 'shark-ai-backend' && ['FREE','PRO','ULTRA'].includes(e.plan)
    ? out('ok','SUBSCRIPTION_ENTITLEMENT',{plan:e.plan,source:e.source})
    : out('unavailable','ENTITLEMENT_UNAVAILABLE');
}
if (!wallet || wallet.status === 'provider_unconfigured') return out('unavailable','WALLET_PROVIDER_UNCONFIGURED');
if (op === 'withdrawal') return out('needs_human','USER_MUST_CONFIRM_WITH_PROVIDER');
if (op === 'deposit') return out('unavailable','VERIFIED_PROVIDER_TRANSACTION_REQUIRED');
if (op === 'onboarding') return wallet.provider && ['available','active'].includes(wallet.status)
  ? out('ok','ACCOUNT_LINKED',{provider:wallet.provider}) : out('unavailable','ONBOARDING_NOT_CONFIRMED');
const observed = Date.parse(wallet.observed_at);
const age = Date.now() - observed;
if (!['available','active'].includes(wallet.status) || typeof wallet.source !== 'string' || !wallet.source.trim() ||
    !Number.isFinite(age) || age < 0 || age > 300000 || !/^[A-Z]{3}$/.test(wallet.currency) ||
    typeof wallet.balance_minor !== 'string' || !/^(0|[1-9]\d{0,23})$/.test(wallet.balance_minor)) return out('unavailable','UNVERIFIED_OR_STALE_BALANCE');
return out('ok','VERIFIED_WALLET_BALANCE',{available_minor:wallet.balance_minor,currency:wallet.currency,provider:wallet.provider,observed_at:wallet.observed_at,source:wallet.source});
